<?php
namespace Delnavazan\Platform\Core\Infrastructure\Repository;

/** Transactional persistence for the bounded Student account-claim invitation aggregate. */
final class StudentAccountClaimInvitationRepository {
    private string $prefix;
    public function __construct(){global $wpdb;$this->prefix=$wpdb->prefix.'dzn_';}
    /** Safe operator projection: lifecycle facts only, never token/command digests. */
    public function lifecycleRows(int $limit=100):array{global $wpdb;$limit=max(1,min($limit,100));return $wpdb->get_results("SELECT i.student_id,i.state,i.current_generation,i.created_at,i.updated_at,i.claimed_at,i.claimed_principal_id,i.revoked_at,i.revocation_reason_code,g.state AS generation_state,g.generation_number,g.issued_at,g.expires_at,g.claimed_at AS generation_claimed_at,g.claimed_principal_id AS generation_claimed_principal_id,g.revoked_at AS generation_revoked_at,g.superseded_at,g.replacement_reason_code FROM {$this->prefix}student_account_claim_invitations i LEFT JOIN {$this->prefix}student_account_claim_generations g ON g.invitation_id=i.id AND g.generation_number=i.current_generation ORDER BY i.updated_at DESC LIMIT {$limit}")?:array();}
    public function begin():void{global $wpdb;if($wpdb->query('START TRANSACTION')===false)throw new \RuntimeException('Claim invitation transaction start failed');}
    public function commit():void{global $wpdb;if($wpdb->query('COMMIT')===false)throw new \RuntimeException('Claim invitation transaction commit failed');}
    public function rollback():void{global $wpdb;$wpdb->query('ROLLBACK');}
    public function studentForUpdate(int $studentId):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->prefix}students WHERE id=%d FOR UPDATE",$studentId));}
    public function invitationForStudentForUpdate(int $studentId):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->prefix}student_account_claim_invitations WHERE student_id=%d FOR UPDATE",$studentId));}
    public function generationForCommandForUpdate(string $commandDigest):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT g.*,i.student_id FROM {$this->prefix}student_account_claim_generations g INNER JOIN {$this->prefix}student_account_claim_invitations i ON i.id=g.invitation_id WHERE g.command_digest=%s FOR UPDATE",$commandDigest));}
    public function claimContextForTokenForUpdate(string $tokenDigest):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT g.*,i.student_id,i.state AS invitation_state,i.current_generation FROM {$this->prefix}student_account_claim_generations g INNER JOIN {$this->prefix}student_account_claim_invitations i ON i.id=g.invitation_id WHERE g.token_digest=%s FOR UPDATE",$tokenDigest));}
    public function activePrincipalForStudentForUpdate(int $studentId):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT id,wordpress_user_id FROM {$this->prefix}student_principal_links WHERE student_id=%d AND status='active' AND active_slot=1 AND revoked_at IS NULL FOR UPDATE",$studentId));}
    public function activePrincipalForUserForUpdate(int $userId):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT id,student_id FROM {$this->prefix}student_principal_links WHERE wordpress_user_id=%d AND status='active' AND active_slot=1 AND revoked_at IS NULL FOR UPDATE",$userId));}
    public function wordpressUserForUpdate(int $userId):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT ID FROM {$wpdb->users} WHERE ID=%d FOR UPDATE",$userId));}
    public function insertInvitation(array $data):int{global $wpdb;if($wpdb->insert($this->prefix.'student_account_claim_invitations',$data)===false)throw new \RuntimeException('Claim invitation persistence failed');return(int)$wpdb->insert_id;}
    public function insertGeneration(array $data):int{global $wpdb;if($wpdb->insert($this->prefix.'student_account_claim_generations',$data)===false)throw new \RuntimeException('Claim invitation generation persistence failed');return(int)$wpdb->insert_id;}
    public function updateInvitation(int $id,array $data):void{global $wpdb;if($wpdb->update($this->prefix.'student_account_claim_invitations',$data,array('id'=>$id))===false)throw new \RuntimeException('Claim invitation update failed');}
    public function supersedeActiveGenerations(int $invitationId,string $reason,string $now,int $actor):int{global $wpdb;$n=$wpdb->query($wpdb->prepare("UPDATE {$this->prefix}student_account_claim_generations SET state='superseded',active_slot=NULL,superseded_at=%s,replacement_reason_code=%s,updated_at=%s,updated_by=%d WHERE invitation_id=%d AND state='active' AND active_slot=1",$now,$reason,$now,$actor,$invitationId));if($n===false)throw new \RuntimeException('Claim invitation replacement failed');return$n;}
    public function consumeGeneration(object $context,int $userId,string $now):void{global $wpdb;$n=$wpdb->query($wpdb->prepare("UPDATE {$this->prefix}student_account_claim_generations SET state='claimed',active_slot=NULL,claimed_at=%s,claimed_principal_id=%d,updated_at=%s,updated_by=%d WHERE id=%d AND invitation_id=%d AND state='active' AND active_slot=1",$now,$userId,$now,$userId,(int)$context->id,(int)$context->invitation_id));if($n!==1)throw new \RuntimeException('Claim invitation generation changed during acceptance');$n=$wpdb->query($wpdb->prepare("UPDATE {$this->prefix}student_account_claim_invitations SET state='claimed',claimed_at=%s,claimed_principal_id=%d,updated_at=%s,updated_by=%d WHERE id=%d AND state='active' AND current_generation=%d",$now,$userId,$now,$userId,(int)$context->invitation_id,(int)$context->generation_number));if($n!==1)throw new \RuntimeException('Claim invitation changed during acceptance');$this->insertEvent(array('uid'=>\Delnavazan\Platform\Core\Support\Identifier::uid(),'invitation_id'=>(int)$context->invitation_id,'generation_id'=>(int)$context->id,'event_sequence'=>$this->nextEventSequence((int)$context->invitation_id),'event_type'=>'claimed','from_state'=>'active','to_state'=>'claimed','reason_code'=>null,'principal_user_id'=>$userId,'occurred_at'=>$now,'recorded_at'=>$now,'recorded_by'=>$userId,'created_at'=>$now,'created_by'=>$userId));}
    public function nextEventSequence(int $invitationId):int{global $wpdb;return 1+(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(MAX(event_sequence),0) FROM {$this->prefix}student_account_claim_events WHERE invitation_id=%d",$invitationId));}
    public function insertEvent(array $data):void{global $wpdb;if($wpdb->insert($this->prefix.'student_account_claim_events',$data)===false)throw new \RuntimeException('Claim invitation audit persistence failed');}
    /** The one #220 intent for a generation.  It shares the caller's transaction with issuance. */
    public function notificationIntentForKeyForUpdate(string $idempotencyKey):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->prefix}platform_outbox WHERE idempotency_key=%s AND event_type='STUDENT_ACCOUNT_CLAIM_ISSUED' FOR UPDATE",$idempotencyKey));}
    /** Lifecycle-safe projection for one invitation/generation pair; never selects token material. */
    public function lifecycleForGeneration(int $invitationId,int $generationId):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT i.id AS invitation_id,i.state AS invitation_state,i.current_generation,g.id AS generation_id,g.generation_number,g.state AS generation_state,g.expires_at FROM {$this->prefix}student_account_claim_invitations i INNER JOIN {$this->prefix}student_account_claim_generations g ON g.invitation_id=i.id WHERE i.id=%d AND g.id=%d LIMIT 1",$invitationId,$generationId));}
    public function insertNotificationIntent(int $invitationId,string $idempotencyKey,string $now):int{global $wpdb;
        if($wpdb->insert($this->prefix.'platform_outbox',array('aggregate_type'=>'student_account_claim','aggregate_id'=>$invitationId,'event_type'=>'STUDENT_ACCOUNT_CLAIM_ISSUED','invitation_id'=>null,'generation_id'=>null,'idempotency_key'=>$idempotencyKey,'status'=>'pending','available_at'=>$now,'leased_at'=>null,'processed_at'=>null,'attempt_count'=>0,'created_at'=>$now))===false)throw new \RuntimeException('Student account claim notification intent persistence failed');
        return(int)$wpdb->insert_id;
    }
}
